; div.asm -- chapter 10: sixteen bits divided by eight
; generated by gen10.py
        INCLUDE "msx.inc"
        OUTPUT "div.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
n       EQU RAM_START          ; the number divided, 0 to 65,535
qsum    EQU RAM_START + 2      ; 32 bits: the quotients added up
rsum    EQU RAM_START + 6      ; 32 bits: the remainders added up
qmix    EQU RAM_START + 10     ; 16 bits: the quotients mixed with XOR
quo     EQU RAM_START + 12     ; the timed quotients, two bytes each
rem     EQU RAM_START + 22     ; and their remainders
        xor a
        ld hl, n
        ld b, 12
clr:    ld (hl), a
        inc hl
        djnz clr                ; n and the sums start at 0
        ld hl, 65535
        ld c, 10
d0:     call div                ; 65535 / 10
        ld (quo+0), hl
        ld (rem+0), a
        ld hl, 740
        ld c, 10
d1:     call div                ; 740 / 10
        ld (quo+2), hl
        ld (rem+1), a
        ld hl, 1000
        ld c, 7
d2:     call div                ; 1000 / 7
        ld (quo+4), hl
        ld (rem+2), a
        ld hl, 65535
        ld c, 255
d3:     call div                ; 65535 / 255
        ld (quo+6), hl
        ld (rem+3), a
        ld hl, 40000
        ld c, 200
d4:     call div                ; 40000 / 200
        ld (quo+8), hl
        ld (rem+4), a
every:  ld hl, (n)
        ld c, 10
        call div
        call tally
        ld hl, (n)
        inc hl
        ld (n), hl
        ld a, h
        or l
        jr nz, every            ; until n has gone round to 0
stop:   jr stop

; div: HL = HL / C, and A = the remainder. C from 1 to 255. Uses B.
div:    xor a                   ; A: the remainder, built up a bit at a time
        ld b, 16
dv1:    add hl, hl              ; the top bit of HL into the carry ...
        rla                     ; ... and in at the bottom of the remainder
        jr c, dv2               ; nine bits: certainly C goes
        cp c
        jr c, dv3               ; C does not go
dv2:    sub c                   ; C goes: take it away,
        inc l                   ; and a 1 into the quotient
dv3:    djnz dv1
        ret

; tally: the quotient in HL added into qsum (32 bits) and mixed into qmix
;        with XOR; the remainder in A added into rsum (32 bits)
tally:  ex de, hl
        ld hl, (qsum)
        add hl, de
        ld (qsum), hl
        jr nc, ty1
        ld hl, (qsum + 2)
        inc hl
        ld (qsum + 2), hl
ty1:    ld l, a
        ld h, 0                 ; HL = the remainder
        ld bc, (rsum)
        add hl, bc
        ld (rsum), hl
        jr nc, ty3
        ld hl, (rsum + 2)
        inc hl
        ld (rsum + 2), hl
ty3:    ld a, (qmix)
        xor e
        ld (qmix), a
        ld a, (qmix + 1)
        xor d
        ld (qmix + 1), a
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
